-- sin extrapolar fuera de 1223.75-1240.75 msnm. area_ha es informativa (levantamiento 2004 a la misma cota).
-- Reemplaza la curva "2004 ajustada" (sesgo medio 9 Mm3, máx 22 Mm3 contra la tabla real).
DELETE FROM public.curvas_capacidad WHERE presa_id = 'PRE-002';
INSERT INTO public.curvas_capacidad (id, presa_id, elevacion_msnm, area_ha, volumen_mm3)
